    public static boolean hasSession(Context ctx){OfflineDb db=OfflineDb.get(ctx);return !db.getSetting("web_cookie","").isEmpty()&&!db.getSetting("web_csrf","").isEmpty();}

    public static void login(Context ctx,String login,String password) throws Exception{
        OfflineDb db=OfflineDb.get(ctx);
        Response first=request(ctx,"GET","login.php",(byte[])null,null,false,null);
        String csrf=extractCsrf(first.body);if(csrf.isEmpty())throw new IllegalStateException("Não foi possível preparar a sessão do aplicativo.");
        Map<String,String> f=new LinkedHashMap<>();f.put("csrf",csrf);f.put("action","login");f.put("login",login);f.put("senha",password);
        Response r=request(ctx,"POST","action.php",form(f).getBytes(StandardCharsets.UTF_8),"application/x-www-form-urlencoded; charset=utf-8",false,null);
        String loc=r.location==null?"":r.location;if((r.code<300||r.code>=400)&&r.code!=200)throw new IllegalStateException("Não foi possível abrir a sessão de dados.");if(loc.contains("login.php")||loc.contains("erro="))throw new IllegalStateException("Usuário ou senha inválidos.");
        db.putSetting("web_csrf",csrf);
        Response verify=request(ctx,"GET","campo.php",(byte[])null,null,false,null);if(verify.code>=400||verify.body.contains("name=\"action\" value=\"login\""))throw new IllegalStateException("A sessão de dados não pôde ser confirmada.");
    }

