        for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r==null)continue;int pid=r.optInt("produtor_id");if(pid>0&&!prodMap.containsKey(pid)){JSONObject p=new JSONObject();p.put("id",pid);p.put("nome",r.optString("produtor"));p.put("cpf",r.optString("cpf"));p.put("cod_fornecedor",r.optString("cod_fornecedor"));p.put("telefone",r.optString("telefone"));p.put("cidade",r.optString("cidade"));p.put("status_atual",r.optString("status"));prodMap.put(pid,p);}JSONObject pl=new JSONObject(r.toString());pl.put("id",r.optInt("plantio_id"));pl.put("produtor_id",pid);pl.put("comunidade_nome",r.optString("comunidade"));pl.put("tecnico_nome",r.optString("tecnico"));pl.put("polo_sigla",r.optString("polo"));plantios.put(pl);}for(JSONObject p:prodMap.values())produtores.put(p);

