        JSONArray atividades=parseSelect(programHtml,"atividade_id","nome"),polos=parseSelect(programHtml,"polo_id","nome"),veiculos=parseVehicles(programHtml),checkItems=parseChecklistItems(checklistHtml),aprov=new JSONArray();for(int i=0;i<programas.length();i++){JSONObject p=programas.optJSONObject(i);String st=p==null?"":p.optString("status").toUpperCase(Locale.ROOT);if(st.equals("PENDENTE")||st.equals("PENDENTE_APROVACAO")||st.equals("ENVIADO"))aprov.put(p);}
